content.content:
/**
 * The whole-DRKG neighbour data in `public/drkg/graph/` (contract: index.json,
 * ids.txt, names-extra.json, shard-NNN.bin). Every loader resolves to `null`
 * when its file is missing, so a fresh clone still gets the canvas and the
 * names.json search from `public/drkg/`.
 */

export const GRAPH_DIR = '/drkg/graph/'
const MAGIC = 0x314b4744

export type GraphIndex = {
  version: 1
  entities: number
  triples: number
  shardSize: number
  shards: number
  edgeCap: number
  knnK: number
  knnScope: string
  relations: { name: string; source: string; label: string; head: string; tail: string; count: number }[]
  types: { name: string; count: number }[]
  externalUrl: Record<string, string>
}

type Shard = {
  firstRow: number
  knnK: number
  edgeOffsets: Uint32Array
  edges: Uint32Array
  relOffsets: Uint32Array
  relCounts: Uint32Array
  knnRows: Uint32Array
  knnDist: Float32Array
}

/** One entity's slice of its shard; views, not copies. */
export type EntityGraph = { edges: Uint32Array; relCounts: Uint32Array; knnRows: Uint32Array; knnDist: Float32Array }

export const edgeNbr = (e: number) => e & 0x1ffff
export const edgeRel = (e: number) => (e >>> 17) & 0x7f
export const edgeOut = (e: number) => ((e >>> 24) & 1) === 1
export const relIdx = (e: number) => e >>> 24
export const relCount = (e: number) => e & 0xffffff

// Vite's dev server answers a missing file with index.html (200), so every
// loader validates its shape and maps anything wrong to null.
async function fetchOk(url: string) {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`${url}: ${res.status}`)
  return res
}

function once<T>(fn: () => Promise<T>) {
  let p: Promise<T> | null = null
  return () => {
    p ??= fn().catch((e) => {
      p = null // a later call retries
      throw e
    })
    return p
  }
}

export const loadIndex = once(async (): Promise<GraphIndex | null> => {
  try {
    const idx = (await (await fetchOk(GRAPH_DIR + 'index.json')).json()) as GraphIndex
    return idx?.version === 1 && idx.shardSize > 0 ? idx : null
  } catch {
    return null
  }
})

export const loadIds = once(async (): Promise<string[] | null> => {
  try {
    const ids = (await (await fetchOk(GRAPH_DIR + 'ids.txt')).text()).split('\n')
    if (ids.at(-1) === '') ids.pop()
    return ids.length > 1000 && ids[0].includes('::') ? ids : null
  } catch {
    return null
  }
})

export const loadNamesExtra = once(async (): Promise<Record<string, string>> => {
  try {
    return (await (await fetchOk(GRAPH_DIR + 'names-extra.json')).json()) as Record<string, string>
  } catch {
    return {}
  }
})

const shards = new Map<number, Promise<Shard>>()

function loadShard(s: number) {
  let p = shards.get(s)
  if (p) return p
  p = fetchOk(`${GRAPH_DIR}shard-${String(s).padStart(3, '0')}.bin`)
    .then((r) => r.arrayBuffer())
    .then(decodeShard)
  shards.set(s, p)
  p.catch(() => shards.delete(s))
  return p
}

export function decodeShard(buf: ArrayBuffer): Shard {
  const h = new Uint32Array(buf, 0, 8)
  if (h[0] !== MAGIC) throw new Error('not a DRKG graph shard')
  const [, firstRow, rowCount, nEdges, nRel, knnK] = h
  let o = 32
  const u32 = (n: number) => {
    const a = new Uint32Array(buf, o, n)
    o += n * 4
    return a
  }
  const edgeOffsets = u32(rowCount + 1)
  const edges = u32(nEdges)
  const relOffsets = u32(rowCount + 1)
  const relCounts = u32(nRel)
  const knnRows = u32(rowCount * knnK)
  const knnDist = new Float32Array(buf, o, rowCount * knnK)
  return { firstRow, knnK, edgeOffsets, edges, relOffsets, relCounts, knnRows, knnDist }
}

export async function loadEntity(row: number, index: GraphIndex): Promise<EntityGraph> {
  const sh = await loadShard(Math.floor(row / index.shardSize))
  const i = row - sh.firstRow
  const k = sh.knnK
  return {
    edges: sh.edges.subarray(sh.edgeOffsets[i], sh.edgeOffsets[i + 1]),
    relCounts: sh.relCounts.subarray(sh.relOffsets[i], sh.relOffsets[i + 1]),
    knnRows: sh.knnRows.subarray(i * k, (i + 1) * k),
    knnDist: sh.knnDist.subarray(i * k, (i + 1) * k),
  }
}

/** Longest matching id prefix wins; `{id}` is what follows it. */
export function externalUrl(id: string, map: Record<string, string>) {
  let best = ''
  for (const p in map) if (id.startsWith(p) && p.length > best.length) best = p
  return best ? map[best].replace('{id}', encodeURIComponent(id.slice(best.length))) : null
}

/* ----------------------------------------------------------------- search -- */

export type SearchIndex = { label: string[]; lower: string[]; idLower: string[]; bare: string[] }

/** `label[row]`: the best human name we have, falling back to the id's local part. */
export function buildSearch(n: number, names: Record<string, string>, extra: Record<string, string>, ids: string[] | null): SearchIndex {
  const label = new Array<string>(n)
  const lower = new Array<string>(n)
  const idLower = new Array<string>(n)
  const bare = new Array<string>(n)
  for (let i = 0; i < n; i++) {
    const id = ids?.[i] ?? ''
    const l = names[i] ?? extra[i] ?? (id ? id.slice(id.indexOf('::') + 2) : '')
    label[i] = l
    lower[i] = l.toLowerCase()
    idLower[i] = id.toLowerCase()
    bare[i] = idLower[i].slice(idLower[i].indexOf('::') + 2)
  }
  return { label, lower, idLower, bare }
}

const isWordChar = (c: number) => (c >= 48 && c <= 57) || (c >= 97 && c <= 122)

/** 4 exact · 3 prefix · 2 word-prefix · 1 substring · 0 none. */
function score(s: string, q: string) {
  if (!s) return 0
  const at = s.indexOf(q)
  if (at < 0) return 0
  if (at === 0) return s.length === q.length ? 4 : 3
  for (let k = at; k >= 0; k = s.indexOf(q, k + 1)) if (!isWordChar(s.charCodeAt(k - 1))) return 2
  return 1
}

/** Linear scan: ~97k `indexOf`, a few ms; ties by degree desc. */
export function search(q: string, idx: SearchIndex, degree: Uint32Array | null, types: Uint8Array, only: Set<number>, limit = 30) {
  const query = q.trim().toLowerCase()
  if (!query) return []
  const hits: number[] = []
  const scores = new Float64Array(idx.label.length)
  for (let i = 0; i < idx.label.length; i++) {
    if (only.size && !only.has(types[i])) continue
    const s = Math.max(score(idx.lower[i], query), score(idx.idLower[i], query), score(idx.bare[i], query))
    if (s) {
      hits.push(i)
      scores[i] = s * 1e7 + (degree ? Math.min(degree[i], 9_999_999) : 0)
    }
  }
  hits.sort((a, b) => scores[b] - scores[a])
  return hits.slice(0, limit)
}

/* ---------------------------------------------------------------- self-test -- */

if (import.meta.env?.DEV && typeof window !== 'undefined' && !(window as { __graphDataTested?: boolean }).__graphDataTested) {
  ;(window as { __graphDataTested?: boolean }).__graphDataTested = true
  const e = 70000 | (5 << 17) | (1 << 24)
  console.assert(edgeNbr(e) === 70000 && edgeRel(e) === 5 && edgeOut(e), 'edge decode')
  console.assert(relIdx((9 << 24) | 1234) === 9 && relCount((9 << 24) | 1234) === 1234, 'relCount decode')
  console.assert(score('riluzole', 'riluzole') === 4 && score('riluzole tab', 'ril') === 3 && score('acid riluzole', 'ril') === 2 && score('xriluzole', 'ril') === 1, 'score tiers')
  console.assert(externalUrl('Gene::6647', { 'Gene::': 'g/{id}', 'Gene::66': 'x/{id}' }) === 'x/47', 'longest prefix')
}
import { useCallback, useEffect, useMemo, useState } from 'react'
import { ChevronLeft, ChevronRight, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { loadNames, useDrkg } from '@/components/discovery/drkg-data'
import { cn } from '@/lib/utils'
import { buildSearch, edgeNbr, edgeRel, loadEntity, loadIds, loadIndex, loadNamesExtra, type EntityGraph, type GraphIndex } from './graph-data'
import { GraphCanvas, TypeGlyph, typeHex, type ColorBy } from './graph-canvas'
import { GraphSearch } from './graph-search'
import { GraphInspector, type Suggestion } from './graph-inspector'

const fmt = (n: number) => n.toLocaleString('en-US')
const LABELLED_NEIGHBOURS = 8

const STARTS: { id: string; label: string; note: string }[] = [
  { id: 'Disease::MESH:D000690', label: 'ALS', note: 'disease' },
  { id: 'Compound::DB00740', label: 'Riluzole', note: 'approved' },
  { id: 'Compound::DB12243', label: 'Edaravone', note: 'approved' },
  { id: 'Gene::6647', label: 'SOD1', note: 'gene' },
  { id: 'Gene::23435', label: 'TARDBP', note: 'TDP-43' },
]

function useReducedMotion() {
  const [reduce, setReduce] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduce(mq.matches)
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduce
}

/** The whole DRKG as a browsable map: search, select, walk edges, go back. */
export default function GraphExplorer() {
  const { data, error } = useDrkg()
  const reduce = useReducedMotion()

  const [index, setIndex] = useState<GraphIndex | null | undefined>(undefined)
  const [ids, setIds] = useState<string[] | null>(null)
  const [names, setNames] = useState<Record<string, string> | null>(null)
  const [extra, setExtra] = useState<Record<string, string>>({})
  useEffect(() => {
    // all start on mount; each lands independently
    loadIndex().then(setIndex)
    loadIds().then(setIds)
    loadNamesExtra().then(setExtra)
    loadNames().then(setNames, () => setNames({}))
  }, [])

  const n = data?.types.length ?? 0
  const searchIndex = useMemo(() => (n && names ? buildSearch(n, names, extra, ids && ids.length === n ? ids : null) : null), [n, names, extra, ids])
  const labelOf = useCallback((row: number) => searchIndex?.label[row] ?? names?.[row] ?? '', [searchIndex, names])
  const idRow = useMemo(() => (ids ? new Map(ids.map((id, i) => [id, i])) : null), [ids])

  /* history: Esc pushes `null`, so Back restores what was cleared */
  const [hist, setHist] = useState<{ list: (number | null)[]; pos: number }>({ list: [null], pos: 0 })
  const selected = hist.list[hist.pos]
  const go = useCallback((row: number | null) => {
    setHist((h) => (h.list[h.pos] === row ? h : { list: [...h.list.slice(0, h.pos + 1), row], pos: h.pos + 1 }))
  }, [])
  const step = useCallback((d: number) => setHist((h) => ({ ...h, pos: Math.min(h.list.length - 1, Math.max(0, h.pos + d)) })), [])

  const [relFilter, setRelFilter] = useState<number | null>(null)
  const [showKnn, setShowKnn] = useState(false)
  const [colorBy, setColorBy] = useState<ColorBy>('type')
  const [only, setOnly] = useState<Set<number>>(() => new Set())

  const [entity, setEntity] = useState<{ row: number; graph: EntityGraph | null } | null>(null)
  useEffect(() => {
    setRelFilter(null)
    if (selected === null || !index) return
    let live = true
    loadEntity(selected, index).then(
      (graph) => live && setEntity({ row: selected, graph }),
      () => live && setEntity({ row: selected, graph: null }), // shard missing or corrupt
    )
    return () => {
      live = false
    }
  }, [selected, index])
  const graph = entity && entity.row === selected ? entity.graph : null

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const typing = e.target instanceof HTMLElement && (e.target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))
      if (e.altKey && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
        e.preventDefault() // Alt+Left is the browser's own Back
        step(e.key === 'ArrowLeft' ? -1 : 1)
      } else if (e.key === 'Escape' && !typing && !e.defaultPrevented) go(null)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [go, step])

  /* what the canvas draws for the selection */
  const neighbours = useMemo(() => {
    if (!graph) return null
    const s = new Set<number>()
    for (const e of graph.edges) if (relFilter === null || edgeRel(e) === relFilter) s.add(edgeNbr(e))
    return Uint32Array.from(s)
  }, [graph, relFilter])
  const knn = showKnn && graph ? graph.knnRows : null
  const labels = useMemo(() => {
    if (selected === null) return []
    const deg = data?.degree
    const top = neighbours ? Array.from(neighbours).filter((r) => r !== selected) : []
    if (deg) top.sort((a, b) => deg[b] - deg[a])
    const near = knn ? Array.from(knn.subarray(0, 4)) : []
    return [selected, ...top.slice(0, LABELLED_NEIGHBOURS), ...near].map((row) => ({ row, text: labelOf(row) || `Entity ${row}` }))
  }, [selected, neighbours, knn, data, labelOf])

  const suggestions = useMemo<Suggestion[]>(() => {
    const out: Suggestion[] = []
    for (const s of STARTS) {
      const row = idRow?.get(s.id) ?? (data && s.id === data.scene.als.id ? data.scene.als.row : undefined)
      if (row !== undefined) out.push({ row, label: s.label, note: s.note })
    }
    return out
  }, [idRow, data])

  const typeList = data?.scene.types ?? []
  const toggleType = (i: number) =>
    setOnly((o) => {
      const next = new Set(o)
      if (!next.delete(i)) next.add(i)
      return next.size === typeList.length ? new Set() : next
    })

  const stats = `${fmt(index?.entities ?? 97238)} entities · ${fmt(index?.triples ?? 5874261)} triples · ${fmt(index?.relations.length ?? 107)} relations · ${fmt(typeList.length || 13)} types`

  return (
    <div className="flex h-[calc(100dvh-var(--header-height)-5.5rem)] min-h-[34rem] flex-col gap-3" style={{ colorScheme: 'light' }}>
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
        <div>
          <h2 className="text-lg font-medium text-balance">The whole knowledge graph</h2>
          <p className="text-sm text-muted-foreground tabular-nums">{stats}</p>
        </div>
        <div className="flex items-center gap-2">
          <ToggleGroup
            type="single"
            variant="outline"
            size="sm"
            spacing={0}
            value={colorBy}
            onValueChange={(v) => v && setColorBy(v as ColorBy)}
            aria-label="Colour points by"
            className="bg-card/90"
          >
            <ToggleGroupItem value="type" className="px-2.5 text-xs">Colour by type</ToggleGroupItem>
            <ToggleGroupItem value="cluster" className="px-2.5 text-xs" disabled={!data?.clusters}>
              By island
            </ToggleGroupItem>
          </ToggleGroup>
          <div className="flex items-center">
            <Button variant="outline" size="icon-sm" className="rounded-r-none bg-card/90" aria-label="Back (Alt+Left)" title="Back (Alt+←)" disabled={hist.pos === 0} onClick={() => step(-1)}>
              <ChevronLeft aria-hidden />
            </Button>
            <Button
              variant="outline"
              size="icon-sm"
              className="-ml-px rounded-l-none bg-card/90"
              aria-label="Forward (Alt+Right)"
              title="Forward (Alt+→)"
              disabled={hist.pos === hist.list.length - 1}
              onClick={() => step(1)}
            >
              <ChevronRight aria-hidden />
            </Button>
          </div>
        </div>
      </div>

      <div className="flex min-h-0 flex-1 gap-3">
        <div className="relative isolate min-w-0 flex-1 overflow-hidden rounded-xl bg-card ring-1 ring-border backdrop-blur-md">
          {data ? (
            <GraphCanvas
              className="absolute inset-0"
              data={data}
              colorBy={colorBy}
              only={only}
              selected={selected}
              neighbours={neighbours}
              knn={knn}
              labels={labels}
              reduce={reduce}
              labelOf={labelOf}
              onSelect={go}
            />
          ) : (
            <div className="flex h-full items-center justify-center gap-2 text-sm text-muted-foreground">
              {error ? (
                <span>DRKG layout unavailable ({error}). Run frontend/scripts/drkg_scene.py.</span>
              ) : (
                <>
                  <Loader2 className="size-4 animate-spin" aria-hidden /> Loading 97,238 DRKG entities…
                </>
              )}
            </div>
          )}

          {data ? (
            <>
              <div className="absolute top-3 left-3 z-20 w-[min(26rem,calc(100%-1.5rem))]">
                <GraphSearch
                  index={searchIndex}
                  ids={ids && ids.length === n ? ids : null}
                  degree={data.degree}
                  types={data.types}
                  typeNames={typeList.map((t) => t.name)}
                  only={only}
                  onPick={go}
                />
              </div>

              {/* legend + type filter in one: glyph, colour, name, count */}
              <div className="absolute bottom-12 left-3 z-10 w-52 rounded-lg bg-card/90 p-1.5 shadow-xs ring-1 ring-border backdrop-blur-sm">
                <div className="flex items-baseline justify-between px-1.5 pt-0.5 pb-1">
                  <h3 className="eyebrow">Entity types</h3>
                  {only.size ? (
                    <button type="button" onClick={() => setOnly(new Set())} className="text-[0.6875rem] text-muted-foreground underline underline-offset-2 hover:text-foreground">
                      All
                    </button>
                  ) : null}
                </div>
                <ul>
                  {typeList.map((t, i) => {
                    const on = only.size === 0 || only.has(i)
                    return (
                      <li key={t.name}>
                        <button
                          type="button"
                          aria-pressed={only.has(i)}
                          onClick={() => toggleType(i)}
                          className={cn(
                            'flex w-full items-center gap-2 rounded-md px-1.5 py-0.5 text-left text-xs hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none',
                            only.has(i) && 'bg-accent font-medium',
                          )}
                        >
                          <span className={cn('flex w-3 justify-center', !on && 'opacity-30')}>
                            <TypeGlyph type={t.name} color={colorBy === 'type' ? typeHex(i) : 'var(--foreground)'} size={11} />
                          </span>
                          <span className={cn('min-w-0 flex-1 truncate', !on && 'text-muted-foreground')}>{t.name}</span>
                          <span className="text-muted-foreground tabular-nums">{fmt(t.count)}</span>
                        </button>
                      </li>
                    )
                  })}
                </ul>
              </div>

              <p className="pointer-events-none absolute bottom-3 left-3 z-10 max-w-[calc(100%-1.5rem)] rounded-md bg-card/80 px-2 py-1 text-[0.6875rem] leading-snug text-pretty text-muted-foreground backdrop-blur-sm">
                Layout: 24 k-means islands of 400-d TransE vectors, not distance-preserving. Embedding neighbours are true 400-d L2. · Drag to rotate, scroll to
                zoom, right-drag to pan.
              </p>
            </>
          ) : null}
        </div>

        <aside key={selected ?? 'none'} className="w-[23rem] shrink-0 overflow-y-auto rounded-xl bg-card ring-1 ring-border backdrop-blur-md" aria-label="Entity details">
          {data ? (
            <GraphInspector
              row={selected}
              data={data}
              index={index ?? null}
              ids={ids && ids.length === n ? ids : null}
              entity={graph}
              graphMissing={index === null || (entity?.row === selected && !entity.graph)}
              labelOf={labelOf}
              relFilter={relFilter}
              onRelFilter={setRelFilter}
              showKnn={showKnn}
              onShowKnn={setShowKnn}
              onNavigate={go}
              suggestions={suggestions}
            />
          ) : null}
        </aside>
      </div>
    </div>
  )
}
import { useDeferredValue, useEffect, useId, useMemo, useRef, useState } from 'react'
import { Loader2, Search, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { search, type SearchIndex } from './graph-data'
import { TypeGlyph, typeHex } from './graph-canvas'

const fmt = (n: number) => n.toLocaleString('en-US')
const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform)

/**
 * Always-visible search over every entity's label and id. `/` or Ctrl/Cmd+K
 * focuses it; ArrowUp/Down + Enter pick; Esc closes. No open/close animation:
 * it is keyboard-driven and used constantly.
 */
export function GraphSearch({
  index,
  ids,
  degree,
  types,
  typeNames,
  only,
  onPick,
}: {
  index: SearchIndex | null
  ids: string[] | null
  degree: Uint32Array | null
  types: Uint8Array
  typeNames: string[]
  only: Set<number>
  onPick: (row: number) => void
}) {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const input = useRef<HTMLInputElement>(null)
  const list = useRef<HTMLUListElement>(null)
  const listId = useId()
  const q = useDeferredValue(query)
  const results = useMemo(() => (index ? search(q, index, degree, types, only, 30) : []), [q, index, degree, types, only])
  const stale = q !== query

  useEffect(() => setActive(0), [q, only])

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const typing = e.target instanceof HTMLElement && (e.target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))
      if ((e.key === 'k' && (e.metaKey || e.ctrlKey)) || (e.key === '/' && !typing)) {
        e.preventDefault()
        input.current?.focus()
        input.current?.select()
        setOpen(true)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  useEffect(() => {
    list.current?.querySelector<HTMLElement>(`[data-i="${active}"]`)?.scrollIntoView({ block: 'nearest' })
  }, [active])

  const pick = (row: number) => {
    onPick(row)
    setOpen(false)
    input.current?.blur()
  }

  const show = open && query.trim().length > 0

  return (
    <div className="relative w-full">
      <div className="relative">
        <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <input
          ref={input}
          type="search"
          role="combobox"
          aria-expanded={show}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={show && results[active] !== undefined ? `${listId}-${active}` : undefined}
          aria-label="Search all DRKG entities by name or id"
          placeholder="Search 97,238 entities — riluzole, SOD1, Gene::6647…"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value)
            setOpen(true)
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => setOpen(false)}
          onKeyDown={(e) => {
            if (e.key === 'ArrowDown') {
              e.preventDefault()
              setActive((a) => Math.min(results.length - 1, a + 1))
            } else if (e.key === 'ArrowUp') {
              e.preventDefault()
              setActive((a) => Math.max(0, a - 1))
            } else if (e.key === 'Enter' && results[active] !== undefined) {
              e.preventDefault()
              pick(results[active])
            } else if (e.key === 'Escape') {
              e.preventDefault()
              e.stopPropagation()
              if (query && show) setQuery('')
              else input.current?.blur()
            }
          }}
          className="h-10 w-full rounded-lg bg-card/95 pr-16 pl-9 text-sm shadow-xs ring-1 ring-border outline-none backdrop-blur-sm placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring [&::-webkit-search-cancel-button]:hidden"
        />
        <div className="absolute top-1/2 right-2 flex -translate-y-1/2 items-center gap-1">
          {query ? (
            <button
              type="button"
              aria-label="Clear search"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => setQuery('')}
              className="flex size-6 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground"
            >
              <X className="size-3.5" aria-hidden />
            </button>
          ) : (
            <kbd className="rounded border border-border bg-background px-1.5 font-sans text-[0.6875rem] text-muted-foreground">{isMac ? '⌘K' : '/'}</kbd>
          )}
        </div>
      </div>

      {show ? (
        <div className="absolute top-full right-0 left-0 z-20 mt-1.5 overflow-hidden rounded-lg bg-popover shadow-lg ring-1 ring-border">
          {!index ? (
            <p className="flex items-center gap-2 px-3 py-3 text-sm text-muted-foreground">
              <Loader2 className="size-4 animate-spin" aria-hidden /> Loading names…
            </p>
          ) : results.length === 0 ? (
            <p className="px-3 py-3 text-sm text-muted-foreground">
              {stale ? 'Searching…' : `No entity matches “${query.trim()}”${only.size ? ' in the selected types' : ''}.`}
            </p>
          ) : (
            <ul ref={list} id={listId} role="listbox" aria-label="Matching entities" className={cn('max-h-[min(26rem,60dvh)] overflow-y-auto py-1', stale && 'opacity-70')}>
              {results.map((row, i) => {
                const t = types[row]
                return (
                  <li
                    key={row}
                    id={`${listId}-${i}`}
                    data-i={i}
                    role="option"
                    aria-selected={i === active}
                    onMouseDown={(e) => e.preventDefault()}
                    onMouseMove={() => setActive(i)}
                    onClick={() => pick(row)}
                    className={cn('grid cursor-pointer grid-cols-[0.875rem_minmax(0,1fr)_auto] items-center gap-x-2.5 px-3 py-1.5 text-sm', i === active && 'bg-accent')}
                  >
                    <TypeGlyph type={typeNames[t]} color={typeHex(t)} />
                    <span className="min-w-0">
                      <span className="block truncate font-medium">{index.label[row] || `Entity ${row}`}</span>
                      <span className="block truncate font-mono text-[0.6875rem] text-muted-foreground">{ids?.[row] ?? typeNames[t]}</span>
                    </span>
                    {degree ? <span className="text-xs text-muted-foreground tabular-nums">{fmt(degree[row])}</span> : null}
                  </li>
                )
              })}
            </ul>
          )}
        </div>
      ) : null}
    </div>
  )
}

