const pill = 'rounded-md bg-card/90 px-1.5 py-0.5 text-xs leading-tight text-foreground shadow-xs ring-1 ring-border backdrop-blur-sm'

export function GraphCanvas({
  data,
  colorBy,
  only,
  selected,
  neighbours,
  knn,
  labels,
  reduce,
  labelOf,
  onSelect,
  className,
}: {
  data: DrkgData
  colorBy: ColorBy
  only: Set<number>
  selected: number | null
  neighbours: Uint32Array | null
  knn: Uint32Array | null
  /** entity labels drawn in the scene, selected first */
  labels: Label[]
  reduce: boolean
  labelOf: (row: number) => string
  onSelect: (row: number) => void
  className?: string
}) {
  const [hover, setHover] = useState<{ row: number; x: number; y: number } | null>(null)
  const clusterEls = useRef<(HTMLDivElement | null)[]>([])
  const labelEls = useRef<(HTMLDivElement | null)[]>([])

  const clusters = useMemo(() => data.scene.clusters ?? [], [data])
  const clusterColors = useMemo(() => clusters.map((c) => clusterHex(c.id, c.color)), [clusters])
  const centroids = useMemo(() => {
    const sum = clusters.map(() => new THREE.Vector3())
    const cnt = clusters.map(() => 0)
    const P = data.positions
    if (data.clusters)
      for (let i = 0; i < data.clusters.length; i++) {
        const c = data.clusters[i]
        if (!sum[c]) continue
        sum[c].x += P[i * 3]
        sum[c].y += P[i * 3 + 1]
        sum[c].z += P[i * 3 + 2]
        cnt[c]++
      }
    return sum.map((s, i) => s.divideScalar(Math.max(1, cnt[i])))
  }, [data, clusters])
  // largest islands win label collisions
  const clusterOrder = useMemo(() => clusters.map((_, i) => i).sort((a, b) => clusters[b].size - clusters[a].size), [clusters])
  const orderedCentroids = useMemo(() => clusterOrder.map((i) => centroids[i]), [clusterOrder, centroids])

  useLayoutEffect(() => {
    labelEls.current.length = labels.length
  }, [labels])

  const type = hover ? data.scene.types[data.types[hover.row]]?.name : null

  return (
    <div className={cn('relative isolate overflow-hidden', className)}>
      <Canvas
        camera={{ position: [9, 7, 25], fov: 42, near: 0.05, far: 200 }}
        dpr={[1, 2]}
        gl={{ alpha: true, antialias: true }}
        raycaster={{ params: { Points: { threshold: 0.09 } } } as never}
        onPointerMissed={() => setHover(null)}
        aria-label="3D map of every DRKG entity. Drag to rotate, scroll to zoom, click a point to inspect it."
        className={hover ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
      >
        <World
          data={data}
          colorBy={colorBy}
          clusterColors={clusterColors}
          only={only}
          selected={selected}
          neighbours={neighbours}
          knn={knn}
          reduce={reduce}
          clusterEls={clusterEls}
          centroids={orderedCentroids}
          labelEls={labelEls}
          labels={labels}
          onHover={setHover}
          onSelect={onSelect}
        />
      </Canvas>

      <div className="pointer-events-none absolute inset-0" aria-hidden>
        {clusterOrder.map((ci, i) => (
          <div
            key={ci}
            ref={(el) => void (clusterEls.current[i] = el)}
            className="absolute top-0 left-0 w-max whitespace-nowrap rounded-full bg-card/75 px-2 py-0.5 text-[0.6875rem] leading-tight font-medium text-foreground/80 opacity-0 backdrop-blur-[2px]"
          >
            {clusters[ci].label} <span className="font-normal text-muted-foreground tabular-nums">{clusters[ci].size.toLocaleString('en-US')}</span>
          </div>
        ))}
        {labels.map((l, i) => (
          <div
            key={`${l.row}-${i}`}
            ref={(el) => void (labelEls.current[i] = el)}
            className={cn(pill, 'absolute top-0 left-0 w-max max-w-[14rem] truncate opacity-0', i === 0 && selected === l.row && 'font-medium ring-foreground/30')}
          >
            {l.text}
          </div>
        ))}
      </div>

      {hover ? (
        <div
          className={cn(pill, 'pointer-events-none absolute top-0 left-0 z-10 max-w-xs px-2 py-1')}
          style={{ transform: `translate3d(${hover.x + 14}px, ${hover.y + 14}px, 0)` }}
        >
          <p className="truncate font-medium">{labelOf(hover.row) || `Entity ${hover.row}`}</p>
          <p className="flex items-center gap-1.5 text-muted-foreground">
            {type ? <TypeGlyph type={type} color={typeHex(data.types[hover.row])} size={10} /> : null}
            {type}
            {data.degree ? (
              <>
                {' · '}
                <span className="tabular-nums">{data.degree[hover.row].toLocaleString('en-US')}</span> edges
              </>
            ) : null}
          </p>
        </div>
      ) : null}
    </div>
  )
}

